import sys
a,b = map(int,input().split())
a,b = min(a,b),max(a,b)
if a==1:
    c=b%6
    if c==4:sys.stdout.write(str((b//6)*6 + 2)+'\n')
    elif c==5:sys.stdout.write(str((b//6)*6 + 4)+'\n')
    else:sys.stdout.write(str((b//6)*6)+'\n')
elif a==2:
    if b<=2:sys.stdout.write('0\n')
    elif b==3 or b==7:sys.stdout.write(str((a*b)-2)+'\n')
    else:sys.stdout.write(str(b*2)+'\n')
else:sys.stdout.write(str(a*b)+'\n')

